                >
                  <span className="material-icons text-sm">person</span>
                  <span className="font-semibold">{user?.username || "Admin"}</span>
                  <span className="material-icons text-sm">
                    {showProfileDropdown ? "expand_less" : "expand_more"}
                  </span>
                </button>

                {showProfileDropdown && (
                  <div className="absolute right-0 mt-2 w-56 bg-white rounded-2xl shadow-2xl border border-blue-200 overflow-hidden z-50">
                    <div className="p-4 bg-gradient-to-r from-primary-blue to-primary-teal">
                      <p className="text-white font-semibold">
