      {successMessage && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-4">
          <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded-lg shadow-lg animate-slideUp">
            <p className="font-bold">Success</p>
            <p>{successMessage}</p>
          </div>
        </div>
